from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent.parent))
from rendu import outils
base,p,c,h,w,table,liste,save=outils(2,10)
t=p('L’arbre garde les urgences en tête et réserve le diagnostic de fibromyalgie à une évaluation clinique cohérente. Chaque résultat positif conduit soit à une filière de gravité, soit à un diagnostic associé, soit à la vérification des critères et au projet de soins.','f83-has-depistage','f83-rcp-criteres','p83-rhabdo-menace')
t+=h('Si une menace est présente, la filière urgente précède les scores')
t+=liste([
('Si des myalgies aiguës après effort s’accompagnent de faiblesse ou d’urine foncée, le clinicien recherche une rhabdomyolyse et organise l’évaluation urgente des complications rénales et électrolytiques.',['p83-rhabdo-clinique','p83-rhabdo-menace']),
('Si une faiblesse s’associe à une dysphagie, à une atteinte respiratoire ou cardiaque, le clinicien organise l’évaluation urgente d’une myopathie potentiellement grave.',['p83-myopathies-gravite']),
('Si un traumatisme fait suspecter un syndrome aigu des loges, la filière chirurgicale urgente s’active ; une fois le diagnostic posé, la décompression ne doit pas être différée.',['p83-boast-loges-0','p83-boast-loges-3']),
('Si une douleur rachidienne s’accompagne d’un déficit moteur ou de signes sphinctériens et périnéaux, le clinicien organise une imagerie immédiate et un avis neurochirurgical.',['pa17-lomb22-queue','pa17-lomb22-urgence']),
('Si une association médicamenteuse sérotoninergique précède hyperthermie, agitation et anomalies neuromusculaires, le clinicien arrête les médicaments concernés et instaure le traitement symptomatique du syndrome suspecté.',['aips-f83-dulox-serotonine','aips-f83-dulox-interactions']),
('Si une idéation suicidaire est présente, l’orientation psychiatrique intervient sans tarder.',['f83-has-humeur'])])
f=w('Artérite à cellules géantes : signes et temporalité',[
('Le guide suisse décrit notamment des céphalées temporales, une douleur à la mastication, une hypersensibilité du cuir chevelu et des troubles visuels comme une diplopie ou une amaurose transitoire. Ces signes, dans le contexte clinique approprié, imposent de considérer une artérite à cellules géantes plutôt qu’une simple douleur diffuse.',['p83-acg-ch']),
('Le résumé EULAR prévoit un avis spécialisé sous 24 heures pour l’artérite et des glucocorticoïdes sans délai lorsque la suspicion est forte. La PPR isolée peut généralement attendre sa confirmation avant traitement ; le clinicien ne confond donc pas ces deux branches.',['p83-pmr-acg-eular2026'])])
t+=p('Si des signes de '+f+' apparaissent dans un tableau compatible, le clinicien suit la branche vasculaire urgente. L’évaluation ne dépend pas d’un résultat de FIRST ni d’un score de fibromyalgie.','p83-acg-ch','p83-pmr-acg-eular2026','f83-has-orientation')
t+=h('Si le tableau est stable, l’examen et les critères orientent la suite')
t+=liste([
('Si la douleur est surtout régionale avec bande tendue et point gâchette, le clinicien étudie la piste myofasciale et recherche séparément une éventuelle douleur généralisée.',['p83-myofascial-fibro','f83-rcp-symptomes']),
('Si un gonflement articulaire, un déficit systématisé ou une autre anomalie objective est présent, le clinicien recherche et traite le diagnostic associé avec des explorations ciblées.',['f83-has-orientation','f83-has-depistage']),
('Si la douleur est diffuse et chronique avec fatigue ou sommeil non réparateur, le clinicien réalise le bilan minimal et peut utiliser FIRST comme aide de dépistage.',['f83-has-orientation','f83-has-depistage']),
('Si la suspicion persiste, le clinicien vérifie les combinaisons WPI–SSS, la généralisation et la durée des critères révisés.',['f83-rcp-criteres','f83-rcp-annexe2016']),
('Si les critères sont remplis dans un tableau cohérent, le clinicien annonce le diagnostic, explique les mécanismes et organise un projet gradué partagé.',['f83-rcp-criteres-cadre','f83-has-annonce']),
('Si les scores sont proches du seuil ou les anomalies difficiles à interpréter, le clinicien explique une hypothèse de travail, sollicite si besoin un avis ciblé et programme une réévaluation.',['f83-rcp-fluctuation','f83-has-depistage']),
('Si un symptôme nouveau apparaît après le diagnostic, le clinicien répète l’examen approprié avant de l’attribuer à la fibromyalgie.',['f83-has-differentiel','f83-rcp-differentiel'])])
t+=p('Le plan débute par information, activité adaptée et stratégies d’autogestion ; une seconde ligne médicamenteuse se discute si les bénéfices restent insuffisants. Le suivi réévalue fonction, douleur, qualité de vie et sécurité, puis adapte les moyens au lieu d’ajouter automatiquement des médicaments.','f83-eular-strategie','f83-has-principes-med','f83-has-suivi')
save(t)

base,p,c,h,w,table,liste,save=outils(2,11)
t=p('Le cadre suisse provient de la Ligue contre le rhumatisme pour l’information, l’autogestion et les ressources sociales, ainsi que de l’AIPS pour la sécurité des prescriptions. Les recommandations professionnelles EULAR et HAS complètent ce cadre ; leurs dispositifs administratifs français ne sont pas présentés comme des droits suisses.','f83-ligue-autonomie','f83-ligue-social','f83-has-travail','aips-f83-dulox-indications')
t+=h('11.A — Le but combine une cible mesurable et la vie quotidienne')
t+=p('La HAS propose de définir avec le patient des objectifs réalistes de douleur, de fonction ou de qualité de vie ; une diminution d’environ 30 % de l’intensité douloureuse est donnée comme exemple cliniquement pertinent. Cette cible n’est ni une promesse de guérison ni le seul critère de réussite.','f83-has-principes-med')
t+=p('Le plan précise aussi une activité concrète importante pour le patient et la manière d’en suivre l’évolution. La réponse s’apprécie avec les capacités fonctionnelles, les activités quotidiennes, la participation professionnelle, l’humeur et la qualité de vie, pas seulement avec la douleur.','f83-has-annonce','f83-has-suivi')
f=w('PGI-C : quantifier le changement sans inventer un seuil de guérison',[
('L’échelle PGI-C comporte 7 niveaux : 1 correspond à une très forte amélioration, 2 à une forte amélioration, 3 à une légère amélioration et 4 à l’absence de changement. Les niveaux 5, 6 et 7 correspondent respectivement à une légère, forte et très forte aggravation.',['f83-pgic']),
('Le patient peut apprécier le changement du fonctionnement, des symptômes ou de la qualité de vie après une intervention ou au cours du suivi. Plus le score est bas, plus le changement est positif ; l’échelle ne certifie ni une rémission biologique ni la disparition du diagnostic.',['f83-pgic'])])
t+=p('La fenêtre '+f+' permet une mesure partagée du bénéfice ressenti. Le clinicien l’associe aux objectifs fonctionnels et à la tolérance pour décider de maintenir, ajuster ou arrêter une intervention.','f83-pgic','f83-has-suivi','f83-has-principes-med')
t+=h('11.B — Les moyens suivent une chronologie explicite')
f=w('Urgence — conduite chronologique',[
('Le clinicien recherche d’abord une complication aiguë : rhabdomyolyse menaçante, atteinte bulbaire ou respiratoire de myopathie, compression neurologique ou syndrome aigu des loges dans son contexte. Il active la filière urgente correspondante avant de poursuivre le parcours d’une douleur chronique.',['p83-rhabdo-menace','p83-myopathies-gravite','pa17-lomb22-urgence','p83-boast-loges-3']),
('Une forte suspicion d’artérite à cellules géantes impose les glucocorticoïdes sans délai et un avis spécialisé rapide. Une idéation suicidaire impose une orientation psychiatrique sans tarder ; ces actions ne sont pas reportées à la réévaluation de l’exercice ou d’un antidépresseur.',['p83-pmr-acg-eular2026','f83-has-humeur']),
('Si un syndrome sérotoninergique est suspecté, l’AIPS exige l’arrêt immédiat de la duloxétine et des agents sérotoninergiques et un traitement symptomatique. Après la prise en charge de la menace, le dossier de douleur chronique est réévalué avec les nouveaux éléments.',['aips-f83-dulox-interactions','f83-has-differentiel'])])
t+=p('La fenêtre '+f+' garde les urgences séparées du traitement habituel du syndrome. Une fois la situation stable, l’annonce du diagnostic légitime la plainte, explique les mécanismes et donne des informations écrites fiables.','f83-has-annonce')
t+=h('Le socle associe éducation, mouvement et autonomie')
t+=p('EULAR donne une recommandation forte à l’exercice et privilégie d’abord l’éducation et les interventions non pharmacologiques. La HAS place également en première ligne une activité physique personnalisée, l’apprentissage de l’autogestion et le soutien du maintien dans l’emploi.','f83-eular-strategie','f83-eular-exercice','f83-has-messages')
t+=p('L’activité est choisie avec le patient, plaisante, progressive et bien tolérée ; fréquence, intensité et durée s’ajustent à ses capacités. Une prescription uniforme trop ambitieuse ne suit pas cette recommandation, notamment lorsque les symptômes persistent entre les séances.','f83-has-activite','f83-has-programme')
t+=p('La HAS décrit des exercices progressifs de faible à moyenne intensité, d’endurance, de renforcement, de souplesse et d’équilibre, à sec ou dans l’eau. Elle propose 1 à 3 séances par semaine sur 3 mois dans un programme adapté, avec durée et modalités ajustées à la tolérance ; ce cadre n’est pas un calendrier rigide imposé à chaque patient.','f83-has-programme','f83-has-relais')
t+=p('L’apprentissage de l’autonomie commence dès les premières séances. Si l’amélioration de la douleur, de la fatigue, du fonctionnement ou de l’autonomie reste insuffisante, la HAS propose un renouvellement du programme pour 3 mois et/ou un complément de stratégie ; lorsque la situation se stabilise, un relais soutient la poursuite de l’activité.','f83-has-relais')
t+=p('L’autogestion peut fractionner les activités et alterner activité et repos, puis élaborer des stratégies personnelles adaptées. L’éducation thérapeutique répond aux besoins identifiés et peut rompre l’isolement ; une intervention psychologique structurée se discute devant des difficultés d’adaptation ou d’évitement.','f83-has-autogestion','f83-has-psychotherapie')
t+=h('Les comorbidités gardent leur traitement propre')
t+=p('Le clinicien explore les troubles du sommeil et recherche notamment une apnée ou des jambes sans repos. Il traite aussi une anxiété ou une dépression reconnue et surveille l’humeur tout au long du suivi, sans transformer ces troubles en cause obligatoire du syndrome.','f83-has-sommeil','f83-has-humeur')
t+=p('La HAS ne trouve pas d’intérêt démontré aux régimes restrictifs ou aux compléments alimentaires dans la fibromyalgie en dehors de carences avérées. Cette recommandation récente évite de convertir les hypothèses métaboliques ou les propositions plus larges d’un document patient en prescription systématique.','f83-has-messages','f83-ligue-mecanismes')
t+=h('Pharmacologie : bénéfice modeste, indication et AMM visibles')
t+=p('Les médicaments interviennent en seconde ligne et leur bénéfice attendu est modeste. La HAS distingue les douleurs continues, qui peuvent justifier des traitements modulant la douleur, des douleurs incidentes pour lesquelles un antalgique ponctuel peut être discuté selon son indication propre.','f83-has-principes-med','f83-has-antalgiques')
t+=p('Les recommandations européennes envisagent notamment certains antidépresseurs et gabapentinoïdes en fonction des symptômes dominants. Cependant, la liste des indications suisses de Duloxétine axapharm ne comprend pas la fibromyalgie : son emploi pour cette seule indication serait hors AMM suisse, même si une recommandation européenne discute son efficacité.','f83-has-antidepresseurs','f83-has-gabapentinoides','aips-f83-dulox-indications')
t+=p('Le tableau suivant décrit uniquement des posologies AIPS pour des comorbidités autorisées ; il ne crée aucune posologie AIPS de fibromyalgie. Une décision hors AMM pour douleur isolée demande une justification individualisée, une information claire et une réévaluation du bénéfice et du risque ; aucune durée validée par une AMM inexistante n’est inventée.','aips-f83-dulox-indications','aips-f83-dulox-posologie','f83-has-principes-med')
t+=table(['Spécialité et indication exacte','Dose, voie et durée AIPS','Sécurité et extrait de référence'],[
['Duloxétine axapharm — dépression coexistante',p('L’AIPS recommande 60 mg par voie orale une fois par jour, avec ou sans repas, comme dose initiale et d’entretien de la dépression. La réponse apparaît généralement après 2 à 4 semaines ; après effet antidépresseur, le traitement se poursuit plusieurs mois pour prévenir les rechutes.','aips-f83-dulox-posologie'),p('L’autorisation Swissmedic porte le numéro 65781 et l’information est mise à jour en décembre 2024. Les doses supérieures à 60 mg n’ont pas montré d’avantage supplémentaire pertinent en règle générale et sont moins bien tolérées.','aips-f83-dulox-numero','aips-f83-dulox-date','aips-f83-dulox-posologie')],
['Duloxétine axapharm — trouble anxieux généralisé coexistante',p('La dose initiale AIPS est de 30 mg par voie orale une fois par jour ; une réponse insuffisante peut conduire à 60 mg une fois par jour, dose d’entretien habituelle. Si un épisode dépressif est associé, l’AIPS indique 60 mg comme dose initiale et d’entretien.','aips-f83-dulox-posologie'),p('Après effet thérapeutique, l’AIPS recommande plusieurs mois et une réévaluation régulière du bénéfice ; les données à long terme mentionnées vont jusqu’à 12 mois. Ces modalités concernent le trouble anxieux, pas une validation réglementaire de la fibromyalgie.','aips-f83-dulox-posologie','aips-f83-dulox-indications')],
['Fibromyalgie sans indication suisse associée',p('Aucune dose ni durée AIPS spécifique de fibromyalgie n’est disponible dans l’information de cette spécialité. Le clinicien ne transfère pas le schéma d’une autre indication sous une fausse étiquette d’autorisation.','aips-f83-dulox-indications','aips-f83-dulox-posologie'),p('Les objectifs et la place éventuelle d’un essai pharmacologique sont discutés après le socle non médicamenteux ; bénéfice et tolérance décident de la poursuite.','f83-has-principes-med')]])
t+=p('La HAS déconseille les AINS en traitement de fond des douleurs continues et juge les données insuffisantes pour recommander le paracétamol comme traitement de fond. Elle ne recommande pas les corticostéroïdes ni les myorelaxants pour la fibromyalgie ; une indication inflammatoire associée reste une autre décision.','f83-has-antalgiques','f83-has-principes-med')
t+=p('La prudence vis-à-vis des opioïdes reste essentielle : la HAS réserve éventuellement le tramadol à certaines douleurs incidentes et considère son emploi prolongé comme exceptionnel après avis spécialisé. Les autres opioïdes ne sont pas recommandés pour la fibromyalgie ; aucune ordonnance d’opioïde n’est proposée ici.','f83-has-antalgiques')
t+=h('Situations spéciales : l’AIPS prime pour la sécurité de la spécialité')
t+=table(['Situation','Règle applicable'],[
['Atteinte rénale',p('Aucun ajustement n’est nécessaire selon l’AIPS pour une clairance entre 30 et 80 mL/min ; une clairance inférieure à 30 mL/min contre-indique la duloxétine de référence. Le clinicien ne remplace pas ce paramètre par un seuil de DFGe supposé identique.','aips-f83-dulox-posologie','aips-f83-dulox-contre-indications')],
['Atteinte hépatique',p('Une maladie hépatique entraînant une insuffisance hépatique contre-indique le médicament. L’AIPS déconseille également son emploi en présence d’une maladie hépatique ou d’autres traitements susceptibles de provoquer une atteinte hépatique.','aips-f83-dulox-contre-indications','aips-f83-dulox-foie-sodium')],
['Hypertension ou cardiopathie',p('Une hypertension non contrôlée contre-indique l’instauration ; chez un patient hypertendu ou ayant une cardiopathie connue, une surveillance régulière de la pression artérielle est recommandée.','aips-f83-dulox-contre-indications','aips-f83-dulox-surveillance')],
['Sujet âgé',p('L’âge seul ne requiert pas un ajustement, mais la prudence demeure nécessaire. L’AIPS signale notamment le risque d’hyponatrémie chez les personnes âgées, déshydratées ou traitées par diurétiques.','aips-f83-dulox-posologie','aips-f83-dulox-foie-sodium')],
['Grossesse',p('La duloxétine ne doit pas être administrée pendant la grossesse sauf nécessité absolue. Le désir de grossesse ou une grossesse en cours conduit à informer le médecin et à réévaluer la stratégie ; les risques néonataux et obstétricaux ne sont pas banalisés.','aips-f83-dulox-grossesse')],
['Allaitement',p('L’administration de duloxétine n’est pas recommandée pendant l’allaitement dans cette information suisse. Cette restriction médicamenteuse est distincte des règles de contraste radiologique.','aips-f83-dulox-grossesse')],
['Enfant ou adolescent',p('La duloxétine n’est pas indiquée avant 18 ans selon l’AIPS. Le parcours de l’enfant nécessite une appréciation adaptée et ne reproduit pas automatiquement celui de l’adulte.','aips-f83-dulox-posologie','f83-ligue-epidemiologie')],
['Interactions et conduite',p('L’association aux IMAO irréversibles ou aux inhibiteurs puissants du CYP1A2 cités par l’AIPS est contre-indiquée. Les associations sérotoninergiques exposent à un syndrome sérotoninergique ; une sédation ou des vertiges appellent une prudence à la conduite.','aips-f83-dulox-contre-indications','aips-f83-dulox-interactions','aips-f83-dulox-conduite')]])
t+=p('En cas d’exploration radiologique d’une maladie associée, une mère enceinte ou allaitante ayant une atteinte rénale ne reçoit pas de gadolinium selon l’ESUR. Cette exception reste explicite même si l’allaitement peut généralement être poursuivi après un produit macrocyclique en l’absence de cette situation.','pa82-esur-mere-renale','pa82-esur-allaitement')
t+=h('Volet social : conserver la participation et mobiliser les ressources suisses')
t+=p('La Ligue suisse recommande de rechercher un maintien dans l’emploi avec adaptation éventuelle des conditions, des horaires et des activités. Une consultation sociale aide à comprendre les démarches et les possibilités individuelles ; ce cours ne déduit aucun droit automatique à une prestation ni aucun refus automatique sur le seul diagnostic.','f83-ligue-prevention','f83-ligue-social')
t+=p('Le médecin relie le projet de soins aux ressources relationnelles choisies, aux groupes d’entraide et aux associations de patients. Il conserve l’accord du patient pour l’implication de ses proches et évite qu’un programme centré sur les symptômes accentue l’isolement.','f83-ligue-relations','f83-has-annonce')
t+=h('11.C — La surveillance choisit ce qui change une décision')
t+=p('Les consultations sont plus rapprochées au début et jusqu’à stabilisation. Si l’évolution est favorable, la HAS propose ensuite un espacement de 3 à 6 mois ; une anomalie nouvelle, une aggravation ou un effet indésirable conduit à une réévaluation plus précoce.','f83-has-coordination','f83-has-suivi','f83-has-differentiel')
t+=p('Chaque réévaluation reprend douleur, fonction, activité, sommeil, humeur, qualité de vie, travail et consommation médicamenteuse. Chaque renouvellement pharmacologique recherche aussi efficacité ressentie, tolérance, automédication et mésusage avant de décider de la poursuite.','f83-has-suivi','f83-has-principes-med')
t+=p('Sous duloxétine, une surveillance rapprochée des idées suicidaires, de l’agitation et de l’aggravation dépressive est particulièrement importante au début, lors des modifications de dose et à l’arrêt. Une suspicion de syndrome sérotoninergique exige un arrêt immédiat ; des symptômes évocateurs d’hyponatrémie ou d’atteinte hépatique imposent une évaluation médicale.','aips-f83-dulox-surveillance','aips-f83-dulox-foie-sodium','aips-f83-dulox-interactions')
t+=p('Hors urgence toxicologique, l’arrêt après plus d’une semaine de traitement se fait généralement par diminution progressive sur 1 à 2 semaines selon l’AIPS, avec adaptation au patient. Le clinicien distingue donc un arrêt urgent pour complication d’une interruption planifiée destinée à réduire les symptômes de sevrage.','aips-f83-dulox-posologie','aips-f83-dulox-interactions')
t+=h('11.D — Pronostic et continuité : des critères explicites plutôt qu’une guérison promise')
t+=p('La fibromyalgie peut fluctuer et franchir les seuils symptomatiques dans les deux sens ; un score plus bas ne prouve pas une réparation tissulaire. L’objectif est une amélioration soutenable du fonctionnement, des symptômes et de la qualité de vie avec un plan compris et ajustable.','f83-rcp-fluctuation','f83-has-suivi')
t+=liste([
('La menace aiguë éventuelle a été évaluée et orientée dans la filière appropriée, avant le retour au suivi chronique.',['p83-rhabdo-menace','pa17-lomb22-urgence','f83-has-humeur']),
('Le diagnostic ou l’hypothèse de travail est expliqué, avec les comorbidités reconnues et les signes qui justifieront une nouvelle consultation.',['f83-has-annonce','f83-rcp-fluctuation']),
('Le patient connaît les objectifs partagés et les modalités de poursuite d’une activité adaptée en autonomie ou avec soutien.',['f83-has-annonce','f83-has-relais']),
('Les traitements ont une indication visible, une tolérance réévaluée et une décision de poursuite ou d’arrêt explicitée.',['f83-has-principes-med','aips-f83-dulox-indications']),
('Un médecin coordonnateur, une échéance de suivi et les relais utiles sont identifiés.',['f83-has-coordination','f83-has-suivi']),
('Les difficultés sociales ou professionnelles identifiées disposent d’un relais adapté, sans transposition des dispositifs administratifs français.',['f83-ligue-social','f83-has-travail'])])
t+=p('Ces éléments organisent une continuité ambulatoire ; ils ne constituent pas une échelle validée de sortie ni des critères biologiques de guérison. Si les douleurs restent résistantes ou la situation complexe, un avis spécialisé en douleur ou dans la discipline pertinente complète le suivi coordonné.','f83-has-coordination','f83-has-suivi','f83-rcp-coexistence')
save(t)
